import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

export async function generateAgents(root, check = false) {
  const contract = (await readFile(path.join(root, "docs/agent-contracts/change-evaluator.md"), "utf8")).trim();
  const description = "Read-only review of AppLibrary correctness, static export, safety, and acceptance evidence.";
  const outputs = {
    ".codex/agents/change-evaluator.toml": `# Generated by npm run generate. Do not edit directly.\nname = "change-evaluator"\ndescription = ${JSON.stringify(description)}\nsandbox_mode = "read-only"\ndeveloper_instructions = ${JSON.stringify(contract)}\n`,
    ".claude/agents/change-evaluator.md": `---\nname: change-evaluator\ndescription: ${JSON.stringify(description)}\nmodel: inherit\ntools: Read, Grep, Glob\n---\n\n<!-- Generated by npm run generate. Do not edit directly. -->\n\n${contract}\n`,
  };
  const errors = [];
  for (const [file, expected] of Object.entries(outputs)) {
    if (check) {
      if (await readFile(path.join(root, file), "utf8").catch(() => "") !== expected) errors.push(`Stale generated file: ${file}`);
    } else {
      await mkdir(path.dirname(path.join(root, file)), { recursive: true });
      await writeFile(path.join(root, file), expected);
    }
  }
  return errors;
}

if (path.resolve(process.argv[1] ?? "") === fileURLToPath(import.meta.url)) {
  const errors = await generateAgents(process.cwd(), process.argv.includes("--check"));
  if (errors.length) { errors.forEach((error) => console.error(error)); process.exitCode = 1; }
  else process.stdout.write("Agent wrappers synchronized\n");
}
